INSERT INTO meditation_library_items
  (id,kind,section,title_en,title_hi,description_en,description_hi,preparation_en,preparation_hi,duration_seconds,steps,published,sort_order,updated_at)
VALUES
('8e0bc1a0-6ce8-4000-8000-000000000301','practice','yoga','Seated shoulder flow','बैठकर कंधों का अभ्यास','A gentle chair session with shoulder and hand movements.','कुर्सी पर बैठकर कंधों और हाथों की हल्की हरकतें।','Sit on a stable chair. Keep each movement small and stop if it hurts.','मज़बूत कुर्सी पर बैठें। हल्की हरकतें करें और दर्द हो तो रुकें।',150,'[{"title_en": "A comfortable seat", "title_hi": "आराम से बैठें", "instruction_en": "Place both feet on the floor and rest your hands on your legs.", "instruction_hi": "दोनों पैर ज़मीन पर रखें और हाथ पैरों पर टिकाएँ।", "seconds": 30}, {"title_en": "Shoulders up and down", "title_hi": "कंधे ऊपर और नीचे", "instruction_en": "Lift your shoulders a little, then let them settle. Rest between movements.", "instruction_hi": "कंधे थोड़ा उठाएँ और फिर ढीले छोड़ें। हरकतों के बीच आराम करें।", "seconds": 60}, {"title_en": "Open your hands", "title_hi": "हाथ खोलें", "instruction_en": "Spread your fingers gently and let them relax. Finish with your hands resting.", "instruction_hi": "उँगलियाँ धीरे फैलाएँ और फिर ढीली छोड़ें। अंत में हाथों को आराम दें।", "seconds": 60}]'::jsonb,false,301,date_trunc('milliseconds',now())),
('8e0bc1a0-6ce8-4000-8000-000000000302','practice','yoga','Seated mountain and rest','बैठकर पर्वत मुद्रा और विश्राम','Alternate between an upright seat and a relaxed pause.','आराम से सीधे बैठें और बीच में विराम लें।','Use a chair with both feet supported. Never force your posture.','कुर्सी पर बैठें और दोनों पैरों को सहारा दें। अपनी मुद्रा पर ज़ोर न दें।',150,'[{"title_en": "Find support", "title_hi": "सहारा महसूस करें", "instruction_en": "Let the chair support you and notice the floor under your feet.", "instruction_hi": "कुर्सी का सहारा और पैरों के नीचे की ज़मीन महसूस करें।", "seconds": 30}, {"title_en": "Sit tall gently", "title_hi": "सहजता से सीधे बैठें", "instruction_en": "Sit a little taller without stiffening, then return to your usual position.", "instruction_hi": "बिना अकड़े थोड़ा सीधे बैठें, फिर अपनी सामान्य मुद्रा में लौटें।", "seconds": 60}, {"title_en": "Rest and notice", "title_hi": "आराम करें और ध्यान दें", "instruction_en": "Rest your hands and notice your natural breathing.", "instruction_hi": "हाथों को आराम दें और अपनी स्वाभाविक साँस पर ध्यान दें।", "seconds": 60}]'::jsonb,false,302,date_trunc('milliseconds',now())),
('8e0bc1a0-6ce8-4000-8000-000000000303','practice','yoga','Chair reach and reset','कुर्सी पर हाथ बढ़ाने का अभ्यास','Try small forward reaches before a quiet rest.','धीरे-धीरे हाथ आगे बढ़ाएँ, फिर थोड़ा आराम करें।','Sit with both feet supported. Stay within a comfortable range and skip any movement that hurts.','दोनों पैरों को सहारा देकर बैठें। जितना सहज हो उतना ही हाथ बढ़ाएँ। दर्द वाली हरकत छोड़ दें।',150,'[{"title_en": "Settle", "title_hi": "ठहरें", "instruction_en": "Rest with your hands on your thighs and breathe normally.", "instruction_hi": "हाथ जाँघों पर रखें और सामान्य रूप से साँस लें।", "seconds": 30}, {"title_en": "Reach forward", "title_hi": "हाथ आगे बढ़ाएँ", "instruction_en": "Send one hand slightly forward and bring it back. Change sides at your own pace.", "instruction_hi": "एक हाथ थोड़ा आगे बढ़ाकर वापस लाएँ। अपनी गति से दूसरा हाथ आज़माएँ।", "seconds": 60}, {"title_en": "Return to rest", "title_hi": "आराम की मुद्रा में लौटें", "instruction_en": "Let both hands rest and give yourself a quiet moment.", "instruction_hi": "दोनों हाथों को आराम दें और कुछ पल शांत बैठें।", "seconds": 60}]'::jsonb,false,303,date_trunc('milliseconds',now())),
('8e0bc1a0-6ce8-4000-8000-000000000304','practice','grounding','Five quiet moments','पाँच शांत पल','Pause to notice your surroundings and how you are supported.','अपने आसपास और शरीर को मिले सहारे पर ध्यान दें।','Choose a safe place to pause. Keep your eyes open if you prefer.','रुकने के लिए सुरक्षित जगह चुनें। चाहें तो आँखें खुली रखें।',70,'[{"title_en": "Look", "title_hi": "देखें", "instruction_en": "Notice one object and its shape.", "instruction_hi": "एक वस्तु और उसके आकार को देखें।", "seconds": 20}, {"title_en": "Feel support", "title_hi": "सहारा महसूस करें", "instruction_en": "Notice the surface under your feet or hands.", "instruction_hi": "पैरों या हाथों के नीचे की सतह महसूस करें।", "seconds": 25}, {"title_en": "Return", "title_hi": "वापस लौटें", "instruction_en": "Let your attention return to the room when ready.", "instruction_hi": "तैयार होने पर ध्यान वापस कमरे में लाएँ।", "seconds": 25}]'::jsonb,false,304,date_trunc('milliseconds',now())),
('8e0bc1a0-6ce8-4000-8000-000000000305','practice','focus','Focus on a small detail','एक छोटी चीज़ पर ध्यान','Practice returning your attention to an ordinary detail.','किसी साधारण चीज़ पर अपना ध्यान बार-बार लौटाएँ।','Choose a comfortable seat and one detail you can see or feel.','आराम से बैठें और ऐसी चीज़ चुनें जिसे देख या महसूस कर सकें।',120,'[{"title_en": "Choose a detail", "title_hi": "एक चीज़ चुनें", "instruction_en": "Notice its colour, shape or texture.", "instruction_hi": "उसका रंग, आकार या बनावट देखें।", "seconds": 30}, {"title_en": "Let attention return", "title_hi": "ध्यान वापस लाएँ", "instruction_en": "If your mind wanders, gently come back to the same detail.", "instruction_hi": "मन भटके तो धीरे से उसी चीज़ पर ध्यान लौटाएँ।", "seconds": 60}, {"title_en": "End at your pace", "title_hi": "अपनी गति से पूरा करें", "instruction_en": "Look around and take a moment before moving on.", "instruction_hi": "आगे बढ़ने से पहले आसपास देखें और थोड़ा समय लें।", "seconds": 30}]'::jsonb,false,305,date_trunc('milliseconds',now())),
('8e0bc1a0-6ce8-4000-8000-000000000306','practice','rest','A quieter end to the day','दिन का शांत समापन','Reflect on one ordinary moment, then let it go.','दिन के किसी साधारण पल को याद करें और फिर जाने दें।','Sit somewhere comfortable. Skip the reflection if you prefer and simply notice your breathing.','आराम से बैठें। चाहें तो चिंतन छोड़कर सिर्फ़ अपनी साँस पर ध्यान दें।',150,'[{"title_en": "Arrive", "title_hi": "वर्तमान में आएँ", "instruction_en": "Notice the support under your body.", "instruction_hi": "अपने शरीर के नीचे का सहारा महसूस करें।", "seconds": 30}, {"title_en": "Think of one moment", "title_hi": "एक पल याद करें", "instruction_en": "Recall one small moment from today without needing to change it.", "instruction_hi": "आज का कोई छोटा पल याद करें। उसे बदलने की ज़रूरत नहीं है।", "seconds": 60}, {"title_en": "Let it pass", "title_hi": "उसे जाने दें", "instruction_en": "Bring attention back to the room and rest for a short while.", "instruction_hi": "ध्यान वापस कमरे की ओर लाएँ और थोड़ी देर आराम करें।", "seconds": 60}]'::jsonb,false,306,date_trunc('milliseconds',now()))
